import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      // All queries will suspend by default
      suspense: true,
      // Retry once for transient failures
      retry: 1,
      // Keep stale data visible for 5 seconds
      staleTime: 5_000,
    },
  },
});

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <SuspenseUserList />
    </QueryClientProvider>
  );
}

function SuspenseUserList() {
  // No isLoading check needed â€” component suspends here
  const { data: users } = useQuery({
    queryKey: ['users'],
    queryFn: () => fetch('/api/users').then((r) => r.json()),
  });

  return (
    <ul>
      {users?.map((user) => (
        <li key={user.id}>{user.name}</li>
      ))}
    </ul>
  );
}

function LoadingFallback() {
  return <p className="loading">Loading usersâ€¦</p>;
}

// Wrap at the router or layout level
function AppLayout({ children }: { children: React.ReactNode }) {
  return (
    <Suspense fallback={<LoadingFallback />}>
      {children}
    </Suspense>
  );
}

function UserProfile({ userId }: { userId: string }) {
  const { data: user } = useQuery({
    queryKey: ['user', userId],
    queryFn: () => fetchUser(userId),
    // Only this query suspends
    suspense: true,
    enabled: !!userId,
  });

  return <h1>{user.name}</h1>;
}

function Page() {
  return (
    <Suspense fallback={<ProfileSkeleton />}>
      <UserProfile userId="123" />
    </Suspense>
  );
}
